args.query:
\d api.application
\d api.app_user
\d reg.counterparty
select rolname from pg_roles where rolname !~ '^pg_';
select * from api.app_user;
select grantee,table_name,privilege_type from information_schema.table_privileges where table_schema in ('api','reg');
select polrelid::regclass,polname,polcmd,pg_get_expr(polqual,polrelid) from pg_policy;
select relname,relrowsecurity,relkind from pg_class where relnamespace in ('api'::regnamespace) ;
select tgname,tgrelid::regclass from pg_trigger where not tgisinternal;

select * from api.status;
select proname,prosecdef,pg_get_functiondef(oid) from pg_proc where pronamespace::regnamespace::text in ('priv','api');
select user_name from (select 1 user_name) x;
\du+ authenticator
select srvoptions from pg_foreign_server;

select * from pg_user_mappings;
create table api.contract(
 id serial primary key,
 number text not null unique,
 application_id integer not null references api.application(id),
 amount numeric not null check (amount>0),
 signed_on date not null default current_date,
 status text not null default 'Проект' check (status in ('Проект','Подписан')));
create index on api.contract(application_id);
create function priv.check_contract() returns trigger language plpgsql security definer set search_path to 'api' as $$
begin
 if not exists (select 1 from api.application where id=NEW.application_id and status_id=priv.status_id('Одобрена')) then
  raise exception 'договор можно заключить только по одобренной заявке' using errcode='check_violation';
 end if;
 return NEW;
end $$;
create trigger check_contract before insert or update on api.contract for each row execute function priv.check_contract();
create function priv.contract_company(int) returns text language sql stable security definer set search_path to 'api' as $$ select company_inn from api.application where id=$1 $$;
alter table api.contract enable row level security;
create policy admin_all on api.contract to fund_admin using (true) with check (true);
create policy lawyer_all on api.contract to lawyer using (true) with check (true);
create policy applicant_read on api.contract for select to applicant using (priv.contract_company(application_id)=priv.my_company());
grant select,insert,update,delete on api.contract to fund_admin;
grant select,insert,update on api.contract to lawyer;
grant select on api.contract to applicant;
grant usage on sequence api.contract_id_seq to fund_admin,lawyer;
grant usage on schema api to lawyer;
grant select on api.application, api.status to lawyer;
create policy lawyer_read on api.application for select to lawyer using (true);
grant usage on schema priv to lawyer;
grant execute on function priv.my_company(), priv.status_ord(int), priv.status_id(text) to lawyer;
update api.app_user set role='lawyer' where login='lawyer1';
create view api.company as select inn, legal_name, funding_limit from reg.counterparty;
grant select on api.company to lawyer, fund_admin;
create view api.limit_balance as
select c.legal_name as company, c.funding_limit,
 a.approved, coalesce(k.contracted,0) as contracted,
 c.funding_limit - coalesce(k.contracted,0) as remaining
from reg.counterparty c
join (select company_inn, sum(amount) approved from api.application where status_id=priv.status_id('Одобрена') group by 1) a on a.company_inn=c.inn
left join (select ap.company_inn, sum(ct.amount) contracted from api.contract ct join api.application ap on ap.id=ct.application_id group by 1) k on k.company_inn=c.inn;
grant select on api.limit_balance to lawyer, fund_admin;
select * from api.limit_balance;
